// src/App.js
import React, { useState, useEffect } from "react";
import QuizBuilderPage from "./pages/QuizBuilderPage";
import QuizComponent from "./components/QuizComponent";
import SignUpModal from "./components/SignUpModal";
import SignInModal from "./components/SignInModal";
import { auth } from "./firebase";
import { onAuthStateChanged, signOut } from "firebase/auth";

function App() {
  const [page, setPage] = useState("dashboard"); // "dashboard" | "builder" | "play"
  const [quizzes, setQuizzes] = useState([]);
  const [selectedQuiz, setSelectedQuiz] = useState(null);
  const [editQuiz, setEditQuiz] = useState(null);

  // Authentication
  const [user, setUser] = useState(null);
  const [showSignUp, setShowSignUp] = useState(false);
  const [showSignIn, setShowSignIn] = useState(false);

  // Load quizzes from localStorage
  useEffect(() => {
    const saved = localStorage.getItem("quizzes");
    if (saved) setQuizzes(JSON.parse(saved));
  }, []);

  useEffect(() => {
    localStorage.setItem("quizzes", JSON.stringify(quizzes));
  }, [quizzes]);

  // Track Firebase auth state
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      if (currentUser) {
        setUser({ email: currentUser.email, uid: currentUser.uid });
      } else {
        setUser(null);
      }
    });
    return () => unsubscribe();
  }, []);

  const addOrUpdateQuiz = (quiz) => {
    if (editQuiz) {
      const updated = quizzes.map((q) => (q.id === editQuiz.id ? quiz : q));
      setQuizzes(updated);
      setEditQuiz(null);
    } else {
      setQuizzes([...quizzes, quiz]);
    }
    setPage("dashboard");
  };

  const deleteQuiz = (quizId) => {
    if (window.confirm("Are you sure you want to delete this quiz?")) {
      setQuizzes(quizzes.filter((q) => q.id !== quizId));
    }
  };

  // Show Sign Up / Sign In if user is not logged in
  if (!user) {
    return (
      <div style={{ textAlign: "center", marginTop: "100px" }}>
        <h1>Welcome to BrainJoy Elite</h1>
        <button onClick={() => setShowSignUp(true)} style={authBtn}>Sign Up</button>
        <button onClick={() => setShowSignIn(true)} style={authBtn}>Sign In</button>

        <SignUpModal
          isOpen={showSignUp}
          onClose={() => setShowSignUp(false)}
          onSignUp={(u) => setUser(u)}
        />

        <SignInModal
          isOpen={showSignIn}
          onClose={() => setShowSignIn(false)}
          onSuccess={(u) => setUser(u)}
        />
      </div>
    );
  }

  return (
    <div style={{ fontFamily: "'Inter', sans-serif", minHeight: "100vh" }}>
      <header style={{ background: "#2b2d42", color: "white", padding: "20px", textAlign: "center" }}>
        <h1>BrainJoy Elite Dashboard</h1>
        <p>Logged in as: {user.email}</p>
        <button onClick={() => signOut(auth)} style={authBtn}>Logout</button>
      </header>

      <nav style={{ display: "flex", justifyContent: "center", padding: "10px", gap: "10px" }}>
        <button onClick={() => { setPage("dashboard"); setEditQuiz(null); }} style={navBtn}>Dashboard</button>
        <button onClick={() => setPage("builder")} style={navBtn}>Create Quiz</button>
      </nav>

      <main style={{ padding: "20px" }}>
        {page === "dashboard" && (
          <>
            <h2>Available Quizzes</h2>
            {quizzes.length === 0 && <p>No quizzes yet. Create one!</p>}
            <ul>
              {quizzes.map((q) => (
                <li key={q.id} style={{ marginBottom: 10 }}>
                  <strong>{q.title}</strong> — {q.subject}{" "}
                  <button onClick={() => { setSelectedQuiz(q); setPage("play"); }} style={playBtn}>Play</button>
                  <button onClick={() => { setEditQuiz(q); setPage("builder"); }} style={editBtn}>Edit</button>
                  <button onClick={() => deleteQuiz(q.id)} style={deleteBtn}>Delete</button>
                </li>
              ))}
            </ul>
          </>
        )}

        {page === "builder" && <QuizBuilderPageWrapper onSave={addOrUpdateQuiz} editQuiz={editQuiz} />}

        {page === "play" && selectedQuiz && <QuizComponent quiz={selectedQuiz} />}
      </main>
    </div>
  );
}

// Wrapper to pass onSave and editQuiz
const QuizBuilderPageWrapper = ({ onSave, editQuiz }) => {
  return <QuizBuilderPage onSave={onSave} editQuiz={editQuiz} />;
};

// Styles
const navBtn = { padding: "8px 16px", border: "none", background: "#ef233c", color: "white", cursor: "pointer", borderRadius: "6px" };
const playBtn = { padding: "4px 10px", marginLeft: "8px", border: "none", background: "#0b6", color: "white", cursor: "pointer", borderRadius: "4px" };
const editBtn = { padding: "4px 10px", marginLeft: "6px", border: "none", background: "#1e90ff", color: "white", cursor: "pointer", borderRadius: "4px" };
const deleteBtn = { padding: "4px 10px", marginLeft: "6px", border: "none", background: "#ff4c4c", color: "white", cursor: "pointer", borderRadius: "4px" };
const authBtn = { padding: "8px 16px", margin: "0 10px", border: "none", background: "#ef233c", color: "white", cursor: "pointer", borderRadius: "6px" };

export default App;
