// src/pages/QuizBuilderPage.js
import React, { useState, useEffect } from "react";
import { v4 as uuidv4 } from "uuid";
import axios from "axios";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";


const QuizBuilderPage = ({ onSave, editQuiz }) => {
  const [title, setTitle] = useState("");
  const [subject, setSubject] = useState("");
  const [questions, setQuestions] = useState([]);
  const [timer, setTimer] = useState(300);
  const [aiTopic, setAiTopic] = useState("");
  const [aiDifficulty, setAiDifficulty] = useState("Medium");
  const [generating, setGenerating] = useState(false);

  useEffect(() => {
    if (editQuiz) {
      setTitle(editQuiz.title);
      setSubject(editQuiz.subject);
      setQuestions(editQuiz.questions);
      setTimer(editQuiz.timer || 300);
    }
  }, [editQuiz]);

  const addQuestion = () => {
    setQuestions([
      ...questions,
      {
        id: uuidv4(),
        text: "",
        type: "MCQ",
        options: ["", ""],
        correct: 0,
        mediaUrl: "",
        mediaFile: null,
        hint: "",
      },
    ]);
  };

  const updateQuestion = (id, updated) => {
    setQuestions(questions.map((q) => (q.id === id ? { ...q, ...updated } : q)));
  };

  const removeQuestion = (id) => {
    setQuestions(questions.filter((q) => q.id !== id));
  };

  const handleMediaUpload = (id, file) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      updateQuestion(id, { mediaUrl: reader.result, mediaFile: file });
    };
    reader.readAsDataURL(file);
  };

  const saveQuiz = () => {
    if (!title || questions.length === 0) {
      alert("Please provide a title and add at least one question.");
      return;
    }
    onSave({
      id: editQuiz ? editQuiz.id : uuidv4(),
      title,
      subject,
      questions,
      timer,
    });
  };

  // AI Question Generation
  const handleGenerateAI = async () => {
    if (!aiTopic) return alert("Please provide a topic for AI question generation.");
    setGenerating(true);
    try {
      const response = await axios.post(
        "https://api.gemini.ai/generate-questions", // Replace with actual endpoint
        {
          topic: aiTopic,
          subject,
          difficulty: aiDifficulty,
          questionTypes: ["MCQ", "ShortAnswer"],
          numberOfQuestions: 3,
        },
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${process.env.REACT_APP_GEMINI_API_KEY}`,
          },
        }
      );

      const aiQuestions = response.data.questions.map((q) => ({
        id: uuidv4(),
        text: q.text,
        type: q.type,
        options: q.options || [],
        correct: q.correct,
        mediaUrl: q.mediaUrl || "",
        mediaFile: null,
        hint: q.hint || "",
      }));

      setQuestions([...questions, ...aiQuestions]);
    } catch (error) {
      console.error("AI generation error:", error);
      alert("Failed to generate AI questions. Check console.");
    } finally {
      setGenerating(false);
    }
  };

  return (
    <div>
      <h2>{editQuiz ? "Edit Quiz" : "Create New Quiz"}</h2>

      {/* Quiz Info */}
      <input
        type="text"
        placeholder="Quiz Title"
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        style={{ marginBottom: 12, width: "60%" }}
      />

      <input
        type="text"
        placeholder="Subject (optional)"
        value={subject}
        onChange={(e) => setSubject(e.target.value)}
        style={{ marginBottom: 12, width: "60%" }}
      />

      <input
        type="number"
        placeholder="Timer (seconds)"
        value={timer}
        onChange={(e) => setTimer(Number(e.target.value))}
        style={{ marginBottom: 12, width: "200px" }}
      />

      {/* AI Question Generation */}
      <div style={{ border: "1px dashed #aaa", padding: 10, marginBottom: 12 }}>
        <h3>AI Question Generation</h3>
        <input
          type="text"
          placeholder="Topic / Prompt"
          value={aiTopic}
          onChange={(e) => setAiTopic(e.target.value)}
          style={{ marginBottom: 6, width: "100%" }}
        />
        <select
          value={aiDifficulty}
          onChange={(e) => setAiDifficulty(e.target.value)}
          style={{ marginBottom: 6 }}
        >
          <option value="Easy">Easy</option>
          <option value="Medium">Medium</option>
          <option value="Hard">Hard</option>
        </select>
        <button onClick={handleGenerateAI} disabled={generating}>
          {generating ? "Generating..." : "Generate AI Questions"}
        </button>
      </div>

      {/* Questions */}
      <h3>Questions</h3>
      {questions.map((q) => (
        <div
          key={q.id}
          style={{ marginBottom: 12, border: "1px solid #ccc", padding: 10 }}
        >
          <label>Question Text:</label>
          <ReactQuill
            theme="snow"
            value={q.text}
            onChange={(val) => updateQuestion(q.id, { text: val })}
          />

          <label>Question Type:</label>
          <select
            value={q.type}
            onChange={(e) => updateQuestion(q.id, { type: e.target.value })}
          >
            <option value="MCQ">MCQ</option>
            <option value="TrueFalse">True/False</option>
            <option value="ShortAnswer">Short Answer</option>
          </select>

          {q.type === "MCQ" &&
            q.options.map((opt, i) => (
              <div key={i}>
                <label>Option {i + 1}:</label>
                <ReactQuill
                  theme="snow"
                  value={opt}
                  onChange={(val) => {
                    const newOpts = [...q.options];
                    newOpts[i] = val;
                    updateQuestion(q.id, { options: newOpts });
                  }}
                />
              </div>
            ))}

          {q.type === "MCQ" && (
            <div>
              Correct Option Index:
              <input
                type="number"
                value={q.correct}
                min={0}
                max={q.options.length - 1}
                onChange={(e) =>
                  updateQuestion(q.id, { correct: Number(e.target.value) })
                }
              />
            </div>
          )}

          {q.type === "TrueFalse" && (
            <div>
              Correct Answer:
              <select
                value={q.correct}
                onChange={(e) =>
                  updateQuestion(q.id, { correct: e.target.value === "true" })
                }
              >
                <option value="true">True</option>
                <option value="false">False</option>
              </select>
            </div>
          )}

          {q.type === "ShortAnswer" && (
            <div>
              Correct Answer:
              <input
                type="text"
                value={q.correct}
                onChange={(e) => updateQuestion(q.id, { correct: e.target.value })}
              />
            </div>
          )}

          {/* Media Upload */}
          <div>
            <label>Attach Image/Video:</label>
            <input
              type="file"
              accept="image/*,video/*"
              onChange={(e) => handleMediaUpload(q.id, e.target.files[0])}
            />
            {q.mediaUrl && (
              <div style={{ marginTop: 6 }}>
                {q.mediaUrl.startsWith("data:image") && (
                  <img src={q.mediaUrl} alt="preview" style={{ maxWidth: 200 }} />
                )}
                {q.mediaUrl.startsWith("data:video") && (
                  <video src={q.mediaUrl} controls style={{ maxWidth: 300 }} />
                )}
              </div>
            )}
          </div>

          <div>
            Hint:
            <input
              type="text"
              value={q.hint || ""}
              onChange={(e) => updateQuestion(q.id, { hint: e.target.value })}
            />
          </div>

          <button onClick={() => removeQuestion(q.id)} style={{ marginTop: 6 }}>
            Remove Question
          </button>
        </div>
      ))}

      <button onClick={addQuestion}>Add Question</button>
      <button onClick={saveQuiz} style={{ marginLeft: 10 }}>
        Save Quiz
      </button>
    </div>
  );
};

export default QuizBuilderPage;

